create or replace function hnk_private.validate_day062_completion_v2(p_evidence jsonb,p_expected_source_sha text)
returns void language plpgsql set search_path='' as $$
declare a jsonb;c jsonb;p jsonb;m jsonb;legacy jsonb;k text;r text;
begin
 if jsonb_typeof(p_evidence) is distinct from 'object' then raise exception 'day062_v2_evidence_object_required'; end if;
 if exists(select 1 from jsonb_object_keys(p_evidence) x where x not in ('protocol_version','source_sha','session_id','mode','active','control','comparison','middle','private_vault_entry_ref','private_vault_e2ee_confirmed','practice_record_no_auditory_free_text_confirmed','persistent_voice_not_reinforced_confirmed','medical_evaluation_not_replaced_confirmed','voluntary_completion_confirmed','final_safety_clear_confirmed','safety_stop_occurred','safety_stop_reason')) then raise exception 'day062_v2_unknown_top_field'; end if;
 if p_evidence->>'protocol_version' is distinct from 'HNK-CHOKMAH-D062-V2' then raise exception 'day062_v2_protocol_invalid'; end if;
 if p_evidence->>'source_sha' is distinct from p_expected_source_sha or p_expected_source_sha is distinct from '56a8aaafbd2d602324ecfb9c06da39563fefaaf6' then raise exception 'day062_v2_source_sha_invalid'; end if;
 if nullif(btrim(p_evidence->>'session_id'),'') is null then raise exception 'day062_v2_session_required'; end if;
 if coalesce(p_evidence->>'mode','first_completion') not in ('first_completion','revisit') then raise exception 'day062_v2_mode_invalid'; end if;
 foreach k in array array['practice_record_no_auditory_free_text_confirmed','persistent_voice_not_reinforced_confirmed','medical_evaluation_not_replaced_confirmed','voluntary_completion_confirmed','final_safety_clear_confirmed'] loop if p_evidence->k is distinct from 'true'::jsonb then raise exception 'day062_v2_completion_boundary_required:%',k; end if; end loop;
 if p_evidence->'safety_stop_occurred' is distinct from 'false'::jsonb or p_evidence->>'safety_stop_reason' is distinct from 'NONE' then raise exception 'day062_v2_unresolved_safety_stop'; end if;
 r:=p_evidence->>'private_vault_entry_ref';
 if r is null then if p_evidence ? 'private_vault_e2ee_confirmed' then raise exception 'day062_v2_vault_flag_without_ref'; end if;
 else if r!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'day062_v2_vault_ref_invalid'; end if;if p_evidence->'private_vault_e2ee_confirmed' is distinct from 'true'::jsonb then raise exception 'day062_v2_vault_e2ee_required'; end if; end if;
 a:=p_evidence->'active';if jsonb_typeof(a) is distinct from 'object' then raise exception 'day062_v2_active_required'; end if;
 if exists(select 1 from jsonb_object_keys(a) x where x not in ('duration_seconds','earplugs_used','internal_sound_present','intensity','comfort','expectation','stability','laterality','safe_quiet_environment_confirmed','earplugs_not_deeply_inserted_confirmed','risk_context_avoided_confirmed','hidden_words_not_sought_confirmed','meaning_not_forced_confirmed','three_external_sounds_on_return_confirmed')) then raise exception 'day062_v2_active_unknown_field'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(a->'duration_seconds'),false) or (a->>'duration_seconds')::integer<1 then raise exception 'day062_v2_active_duration_incomplete'; end if;
 if jsonb_typeof(a->'earplugs_used') is distinct from 'boolean' or jsonb_typeof(a->'internal_sound_present') is distinct from 'boolean' then raise exception 'day062_v2_active_presence_invalid'; end if;
 foreach k in array array['intensity','comfort','expectation','stability'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(a->k),false) or (a->>k)::integer>10 then raise exception 'day062_v2_active_score_invalid:%',k; end if; end loop;
 if a->>'laterality' not in ('NONE','LEFT','RIGHT','BILATERAL','DIFFUSE','UNKNOWN') then raise exception 'day062_v2_active_laterality_invalid'; end if;
 foreach k in array array['safe_quiet_environment_confirmed','earplugs_not_deeply_inserted_confirmed','risk_context_avoided_confirmed','hidden_words_not_sought_confirmed','meaning_not_forced_confirmed','three_external_sounds_on_return_confirmed'] loop if a->k is distinct from 'true'::jsonb then raise exception 'day062_v2_active_boundary_required:%',k; end if; end loop;
 c:=p_evidence->'control';if jsonb_typeof(c) is distinct from 'object' then raise exception 'day062_v2_control_required'; end if;
 if exists(select 1 from jsonb_object_keys(c) x where x not in ('duration_seconds','earplugs_used','internal_sound_present','external_sound_present','intensity','comfort','expectation','stability','laterality','distractions','same_location_confirmed','similar_posture_confirmed','similar_duration_confirmed','meaning_not_forced_confirmed')) then raise exception 'day062_v2_control_unknown_field'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->'duration_seconds'),false) or (c->>'duration_seconds')::integer<1 then raise exception 'day062_v2_control_duration_incomplete'; end if;
 if c->'earplugs_used' is distinct from 'false'::jsonb or jsonb_typeof(c->'internal_sound_present') is distinct from 'boolean' or jsonb_typeof(c->'external_sound_present') is distinct from 'boolean' then raise exception 'day062_v2_control_presence_invalid'; end if;
 foreach k in array array['intensity','comfort','expectation','stability','distractions'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->k),false) or (c->>k)::integer>10 then raise exception 'day062_v2_control_score_invalid:%',k; end if; end loop;
 if c->>'laterality' not in ('NONE','LEFT','RIGHT','BILATERAL','DIFFUSE','UNKNOWN') then raise exception 'day062_v2_control_laterality_invalid'; end if;
 foreach k in array array['same_location_confirmed','similar_posture_confirmed','similar_duration_confirmed','meaning_not_forced_confirmed'] loop if c->k is distinct from 'true'::jsonb then raise exception 'day062_v2_control_boundary_required:%',k; end if; end loop;
 p:=p_evidence->'comparison';if jsonb_typeof(p) is distinct from 'object' then raise exception 'day062_v2_comparison_required'; end if;
 if exists(select 1 from jsonb_object_keys(p) x where x not in ('completed_confirmed','after_both_conditions_confirmed','interpretation_separated_confirmed','external_message_not_claimed_confirmed','spiritual_superiority_not_assigned_confirmed','retrospective_cherry_pick_forbidden_confirmed','acoustic_features_before_meaning_confirmed','null_result_valid_confirmed')) then raise exception 'day062_v2_comparison_unknown_field'; end if;
 foreach k in array array['completed_confirmed','after_both_conditions_confirmed','interpretation_separated_confirmed','external_message_not_claimed_confirmed','spiritual_superiority_not_assigned_confirmed','retrospective_cherry_pick_forbidden_confirmed','acoustic_features_before_meaning_confirmed','null_result_valid_confirmed'] loop if p->k is distinct from 'true'::jsonb then raise exception 'day062_v2_comparison_boundary_required:%',k; end if; end loop;
 m:=p_evidence->'middle';if jsonb_typeof(m) is distinct from 'object' then raise exception 'day062_v2_middle_required'; end if;
 if exists(select 1 from jsonb_object_keys(m) x where x not in ('psalm_98_4_confirmed','yod_zayin_lamed_confirmed','three_breaths_without_earplugs_confirmed','external_internal_simultaneous_awareness_confirmed','datum_named_count','sensation_named_count','traditional_symbol_named_count','open_hypothesis_named_count','thanks_to_god_confirmed','movement_and_return_confirmed','impression_not_automatic_order_confirmed','impression_not_superior_truth_confirmed')) then raise exception 'day062_v2_middle_unknown_field'; end if;
 foreach k in array array['psalm_98_4_confirmed','yod_zayin_lamed_confirmed','three_breaths_without_earplugs_confirmed','external_internal_simultaneous_awareness_confirmed','thanks_to_god_confirmed','movement_and_return_confirmed','impression_not_automatic_order_confirmed','impression_not_superior_truth_confirmed'] loop if m->k is distinct from 'true'::jsonb then raise exception 'day062_v2_middle_boundary_required:%',k; end if; end loop;
 foreach k in array array['datum_named_count','sensation_named_count','traditional_symbol_named_count','open_hypothesis_named_count'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(m->k),false) or (m->>k)::integer<>1 then raise exception 'day062_v2_middle_exact_one_required:%',k; end if; end loop;
 legacy:=jsonb_build_object('protocol_completed',true,'return_confirmed',m->'movement_and_return_confirmed','active_completed',true,'control_completed',true,'comparison_completed',p->'completed_confirmed','interpretation_separated',p->'interpretation_separated_confirmed','external_message_not_claimed',p->'external_message_not_claimed_confirmed','ear_safety_respected',a->'earplugs_not_deeply_inserted_confirmed','risk_context_avoided',a->'risk_context_avoided_confirmed','persistent_voice_not_reinforced',p_evidence->'persistent_voice_not_reinforced_confirmed','safety_clear',p_evidence->'final_safety_clear_confirmed','earplugs_used',a->'earplugs_used','active_sound_present',a->'internal_sound_present','control_sound_present',to_jsonb(((c->>'internal_sound_present')::boolean or (c->>'external_sound_present')::boolean)),'active_seconds',a->'duration_seconds','control_seconds',c->'duration_seconds');
 perform hnk_private.validate_day062_scalar_evidence_v1(legacy);
end$$;

create or replace function hnk_private.enforce_iezalel_062_066_scalar_evidence() returns trigger language plpgsql security definer set search_path='' as $$
declare v_existing boolean;v_source_sha text;v_status text;
begin
 if new.day not in (62,63,64,65,66) or new.state not in ('evidence_pending','complete') then return new;end if;
 select exists(select 1 from public.day_completions where user_id=new.user_id and day=new.day) into v_existing;if v_existing then return new;end if;
 select source_sha,status into v_source_sha,v_status from public.codex_days where day=new.day;if v_status is distinct from 'canon' then raise exception 'iezalel_canonical_day_not_available';end if;
 if new.day=62 then if v_source_sha is distinct from '56a8aaafbd2d602324ecfb9c06da39563fefaaf6' then raise exception 'day062_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D062-V2' then perform hnk_private.validate_day062_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day062_scalar_evidence_v1(new.evidence);end if;
 elsif new.day=63 then if v_source_sha is distinct from 'b9c9872ddf618aff3f515f601b3abfd611dace46' then raise exception 'day063_canonical_source_sha_mismatch';end if;perform hnk_private.validate_day063_scalar_evidence_v1(new.evidence);
 elsif new.day=64 then if v_source_sha is distinct from 'fb05d22be494099a5a1d3e1e0f5480ecc6c072cb' then raise exception 'day064_canonical_source_sha_mismatch';end if;perform hnk_private.validate_day064_scalar_evidence_v1(new.evidence);
 elsif new.day=65 then if v_source_sha is distinct from '8d8cd2a39fb05be283b8326fa258ed547b40f442' then raise exception 'day065_canonical_source_sha_mismatch';end if;perform hnk_private.validate_day065_scalar_evidence_v1(new.evidence);
 else if v_source_sha is distinct from 'a6d48785ee355f734cadda61b0bb3810b125bf5e' then raise exception 'day066_canonical_source_sha_mismatch';end if;perform hnk_private.validate_day066_scalar_evidence_v1(new.evidence);end if;
 return new;
end$$;

do $$ declare v_def text;v_old text;v_new text;begin
 select pg_get_functiondef('hnk_private.validate_completion_contract_v2(text,jsonb,text)'::regprocedure) into v_def;
 if position('when ''day062_v2''' in v_def)=0 then v_old:='  else raise exception ''unsupported_completion_validator:%'',p_validator_key;';if position(v_old in v_def)=0 then raise exception 'day062_dispatcher_patch_anchor_missing';end if;v_new:='  when ''day062_v2'' then perform hnk_private.validate_day062_completion_v2(p_evidence,p_expected_source_sha);'||E'\n'||v_old;v_def:=replace(v_def,v_old,v_new);execute v_def;end if;
end$$;

insert into hnk_private.completion_contract_registry(completion_contract_id,quest_definition_id,day,canonical_source_sha,contract_version,validator_key,status)
values('HNK-CHOKMAH-D062-COMP-V2','HNK-CHOKMAH-D062-V2',62,'56a8aaafbd2d602324ecfb9c06da39563fefaaf6','2.0.0','day062_v2','draft')
on conflict(completion_contract_id) do update set quest_definition_id=excluded.quest_definition_id,day=excluded.day,canonical_source_sha=excluded.canonical_source_sha,contract_version=excluded.contract_version,validator_key=excluded.validator_key,status='draft',updated_at=now();
